"use strict";(self.webpackChunkwoocommerce_restaurant_kitchen_pos_doc=self.webpackChunkwoocommerce_restaurant_kitchen_pos_doc||[]).push([[43],{6501(e,t,a){a.r(t),a.d(t,{_pageData:()=>r,default:()=>s});var n=a(641);const r=JSON.parse('{"path":"/kitchen-customer-screen/sending-orders-from-pos.html","title":"Sending Orders From The POS","lang":"en-US","frontmatter":{"title":"Sending Orders From The POS","description":"How a cashier sends a dine in or take away order to the kitchen from WooCommerce Point of Sale, adds a kitchen note, prints a kitchen receipt and raises the bill afterwards."},"git":{},"filePathRelative":"kitchen-customer-screen/sending-orders-from-pos.md"}'),o={name:"sending-orders-from-pos.md"},s=(0,a(6262).A)(o,[["render",function(e,t,a,r,o,s){const i=(0,n.g2)("RouteLink");return(0,n.uX)(),(0,n.CE)("div",null,[t[3]||(t[3]=(0,n.Fv)('<h1 id="sending-orders-from-the-pos" tabindex="-1"><a class="header-anchor" href="#sending-orders-from-the-pos"><span>Sending Orders From The POS</span></a></h1><p>This page is for the person on the till. Everything here happens inside the Point of Sale at <code>/pos</code> — you never need the WordPress admin.</p><p>There are two ways to send an order to the kitchen, and which one you use depends on whether the order is for a seated table or for take away.</p><h2 id="dine-in-—-send-before-the-bill" tabindex="-1"><a class="header-anchor" href="#dine-in-—-send-before-the-bill"><span>Dine in — send before the bill</span></a></h2><p>A seated table is sent to the kitchen as soon as the order is taken, long before anybody pays.</p><h3 id="_1-open-the-table" tabindex="-1"><a class="header-anchor" href="#_1-open-the-table"><span>1. Open the table</span></a></h3><p>Go to <strong>Dining Tables → Tables</strong>. Tables are colour coded: <strong>green is vacant, red is occupied</strong>. Select a green table to open the booking box, choose the customer — or <strong>Create New Customer</strong> — pick the <strong>Booking Date</strong> and an <strong>Available Booking Slot</strong>, and select <strong>BOOK</strong>.</p><p>The slot list tells you what is available at a glance: a slot somebody already holds is marked <strong>Booked</strong>, and a slot whose time has passed is marked <strong>Expired</strong>. Neither can be chosen.</p><p>Once the table is booked, open the <strong>Bookings</strong> tab, expand the booking for the table you are serving and select <strong>Add Product</strong>.</p><p><img src="/kitchen-and-customer-screen-for-restaurant-pos/images/kitchen-customer-screen/pos-booking-add-product.png" alt="A booking expanded on the Bookings tab, with the Add Product button"></p><p>The POS returns to the product screen with that table now shown in the header, which is what tells the module the order is dine in.</p><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>If the party does not turn up, expand the booking and select <strong>Booking Release</strong>. The table goes back to green and its slot becomes available for somebody else straight away.</p></div><h3 id="_2-build-the-cart" tabindex="-1"><a class="header-anchor" href="#_2-build-the-cart"><span>2. Build the cart</span></a></h3><p>Add the dishes as normal. The cart panel on the right lists them with quantities and the running total.</p><h3 id="_3-select-add-to-prepare" tabindex="-1"><a class="header-anchor" href="#_3-select-add-to-prepare"><span>3. Select Add To Prepare</span></a></h3><p><strong>Add To Prepare</strong> sits at the bottom of the cart panel, under <strong>Hold Cart</strong> and <strong>Pay</strong>.</p><p><img src="/kitchen-and-customer-screen-for-restaurant-pos/images/kitchen-customer-screen/pos-cart-add-to-prepare.png" alt="The POS cart with items and the Add To Prepare button"></p><h3 id="_4-add-a-note-for-the-kitchen" tabindex="-1"><a class="header-anchor" href="#_4-add-a-note-for-the-kitchen"><span>4. Add a note for the kitchen</span></a></h3><p>Selecting the button opens <strong>Add Note For Kitchen</strong>. Type anything the kitchen needs to know — an allergy, a cooking preference, a request to serve two courses together — or leave it blank.</p><p><img src="/kitchen-and-customer-screen-for-restaurant-pos/images/kitchen-customer-screen/pos-kitchen-note-popup.png" alt="The Add Note For Kitchen popup with a note typed in"></p><p>Select <strong>Add</strong>. The ticket is created, the cart is cleared, and the POS moves you to the <strong>Kitchen Orders</strong> tab where you can see it waiting. <strong>Cancel</strong> closes the popup and leaves the cart untouched.</p><div class="hint-container note"><p class="hint-container-title">Note</p><p>No WooCommerce order exists yet. A dine in ticket is a kitchen instruction; the WooCommerce order is created later, when you raise the bill.</p></div><h2 id="take-away-—-send-at-payment" tabindex="-1"><a class="header-anchor" href="#take-away-—-send-at-payment"><span>Take away — send at payment</span></a></h2><p>A take away order is sent to the kitchen when it is paid for, not before.</p><ol><li>Build the cart in take away mode.</li><li>Select <strong>Pay</strong>.</li><li>On the payment page, tick <strong>Add To Prepare</strong>.</li><li>Take the payment as usual.</li></ol><p><img src="/kitchen-and-customer-screen-for-restaurant-pos/images/kitchen-customer-screen/pos-pay-add-to-prepare.png" alt="The Add To Prepare checkbox on the POS payment page"></p><p>As soon as the order is created, the ticket appears on the kitchen board carrying the WooCommerce order number, so the counter and the kitchen are talking about the same number.</p><p>If you leave the box unticked, the order is completed normally and the kitchen never sees it — useful for items that need no preparation.</p><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>The cart <strong>Add To Prepare</strong> button refuses a take away cart with <em>&quot;You can not send order for preapare in take away mode.&quot;</em> That is the module pointing you at this checkbox instead.</p></div><h2 id="the-three-kitchen-tabs" tabindex="-1"><a class="header-anchor" href="#the-three-kitchen-tabs"><span>The three kitchen tabs</span></a></h2><p>With <strong>Restaurant Point of Sale</strong> active, the module adds three tabs to <strong>Dining Tables</strong>.</p><table><thead><tr><th>Tab</th><th>What it lists</th></tr></thead><tbody><tr><td><strong>Kitchen Orders</strong></td><td>Tickets still waiting to be started</td></tr><tr><td><strong>Sent Orders</strong></td><td>Tickets the kitchen has finished and sent out</td></tr><tr><td><strong>All Orders</strong></td><td>On Hold, Preparing and Completed side by side</td></tr></tbody></table><p>Without Restaurant Point of Sale these same three views appear under a <strong>Kitchen</strong> entry in the POS side menu instead.</p><h3 id="kitchen-orders" tabindex="-1"><a class="header-anchor" href="#kitchen-orders"><span>Kitchen Orders</span></a></h3><p>Expand a ticket to see its items and its actions.</p><p><img src="/kitchen-and-customer-screen-for-restaurant-pos/images/kitchen-customer-screen/pos-kitchen-orders.png" alt="The Kitchen Orders tab with a ticket expanded, showing Add More, Delete and Receipt"></p><table><thead><tr><th>Action</th><th>What it does</th></tr></thead><tbody><tr><td><strong>ADD MORE</strong></td><td>Loads the ticket back into the POS cart so you can add more dishes to the same table. Dine in only, and the cart must be empty first.</td></tr><tr><td><strong>DELETE</strong></td><td>Removes the ticket from the kitchen. Use it when a table cancels before the food is started.</td></tr><tr><td><strong>RECEIPT</strong></td><td>Prints the kitchen ticket — product names, quantities, the order number, the date, the customer, the cashier and the note. Prices are deliberately left off.</td></tr><tr><td><strong>THERMAL RECEIPT</strong></td><td>The same ticket sent to a thermal printer. This extra button appears only when the WooCommerce POS Thermal Printer add on is active.</td></tr></tbody></table><div class="hint-container note"><p class="hint-container-title">Note</p><p>With the thermal printer add on active you also get a <strong>Print Thermal Receipt</strong> button when you open a past order under <strong>Orders</strong> in the POS, so a customer bill can be reprinted from the sales history without going back through the kitchen tabs. That button belongs to the thermal printer add on, not to this module.</p></div><h3 id="sent-orders" tabindex="-1"><a class="header-anchor" href="#sent-orders"><span>Sent Orders</span></a></h3><p>The kitchen has finished these and handed them out.</p><p><img src="/kitchen-and-customer-screen-for-restaurant-pos/images/kitchen-customer-screen/pos-sent-orders.png" alt="The Sent Orders tab"></p><p>Select anywhere on a card to expand it and see the items, exactly as on the other tabs.</p><table><thead><tr><th>Action</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Create Bill</strong></td><td>Loads the ticket back into the POS cart, restores the table and the customer, and jumps straight to the payment page. Dine in only. The card is then marked <strong>Bill Created</strong>.</td></tr><tr><td><strong>Back to Hold</strong></td><td>Returns the ticket to the kitchen&#39;s On Hold column, for a plate that has to be remade.</td></tr><tr><td><strong>Read Note</strong></td><td>Shows the kitchen note that was attached when the ticket was sent.</td></tr></tbody></table><h3 id="billing-the-same-table-twice" tabindex="-1"><a class="header-anchor" href="#billing-the-same-table-twice"><span>Billing the same table twice</span></a></h3><p>If <strong>Create Bill</strong> is used on a ticket that already carries the <strong>Bill Created</strong> badge, the POS stops and asks first:</p><blockquote><p><strong>Bill Already Created</strong><br> Bill has already been created for Order #78. Do you want to create it again?</p></blockquote><p><strong>Cancel</strong> leaves everything alone. <strong>Create Again</strong> loads the ticket back into the cart and opens the payment page as normal. It is there to catch the accidental second tap, not to prevent a genuine re-bill.</p><h3 id="all-orders" tabindex="-1"><a class="header-anchor" href="#all-orders"><span>All Orders</span></a></h3><p>A read only view of the three working columns, so the counter can see how busy the kitchen is without walking over to the pass.</p><p><img src="/kitchen-and-customer-screen-for-restaurant-pos/images/kitchen-customer-screen/pos-all-orders.png" alt="The All Orders tab inside the POS"></p><p>On a narrow screen the three columns collapse into one tab per status.</p><h2 id="raising-the-bill-for-a-table" tabindex="-1"><a class="header-anchor" href="#raising-the-bill-for-a-table"><span>Raising the bill for a table</span></a></h2><ol><li>Open <strong>Dining Tables → Sent Orders</strong>.</li><li>Find the ticket for the table and select <strong>Create Bill</strong>.</li><li>The POS loads the items into the cart and opens the payment page.</li><li>Take the payment by cash or by any other method you have set up, then select <strong>Confirm Payment &amp; Generate Invoice</strong>.</li><li>A success message appears with a <strong>PRINT INVOICE</strong> button for the customer&#39;s bill.</li></ol><p>If the cart is not empty, the POS refuses with <em>&quot;Your cart has some products first empty the cart.&quot;</em> Clear the cart and try again.</p><p>The card is marked <strong>Bill Created</strong> once the ticket has been billed, so the same table is not billed twice by mistake.</p><h2 id="messages-you-may-see" tabindex="-1"><a class="header-anchor" href="#messages-you-may-see"><span>Messages you may see</span></a></h2><table><thead><tr><th>Message</th><th>Why</th><th>What to do</th></tr></thead><tbody><tr><td>Cart can not be empty.</td><td><strong>Add To Prepare</strong> with nothing in the cart</td><td>Add the dishes first</td></tr><tr><td>You can not send order for preapare in take away mode.</td><td>The cart is a take away</td><td>Use the payment page checkbox instead</td></tr><tr><td>Please select booking table from booking tab first.</td><td>No table is open</td><td>Open the table from <strong>Dining Tables</strong></td></tr><tr><td>You can not operate this in offline mode</td><td>The till has lost its internet connection</td><td>Restore the connection and try again</td></tr><tr><td>You can not add more products for take away orders.</td><td><strong>ADD MORE</strong> on a take away ticket</td><td>Not supported. Send a second ticket instead</td></tr><tr><td>Your cart has some products first empty the cart.</td><td><strong>ADD MORE</strong> or <strong>Create Bill</strong> with a cart already open</td><td>Clear or park the current cart</td></tr></tbody></table><h2 id="next-step" tabindex="-1"><a class="header-anchor" href="#next-step"><span>Next step</span></a></h2>',58)),(0,n.Lk)("p",null,[t[1]||(t[1]=(0,n.eW)("See what the kitchen does with the ticket in ",-1)),(0,n.bF)(i,{to:"/kitchen-customer-screen/kitchen-screen.html"},{default:(0,n.k6)(()=>[...t[0]||(t[0]=[(0,n.eW)("Kitchen Screen",-1)])]),_:1}),t[2]||(t[2]=(0,n.eW)(".",-1))])])}]])}}]);